<?php
declare(strict_types=1);$pageTitle='Редактор публикации';require_once __DIR__.'/_header.php';$id=(int)($_GET['id']??0);$p=['title'=>'','slug'=>'','excerpt'=>'','content'=>'<p></p>','image_url'=>'','category_id'=>'','status'=>'draft','is_featured'=>0,'published_at'=>date('Y-m-d\TH:i')];if($id){$s=db()->prepare('SELECT * FROM posts WHERE id=? LIMIT 1');$s->execute([$id]);$x=$s->fetch();if(!$x){http_response_code(404);exit('Публикация не найдена.');}$p=$x;$p['published_at']=$p['published_at']?date('Y-m-d\TH:i',strtotime($p['published_at'])):date('Y-m-d\TH:i');}$cats=categories();?><form method="post" action="<?=e(url('admin/save-post.php'))?>" class="form-grid" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$id?>"><div class="field"><label>Заголовок</label><input name="title" value="<?=e($p['title'])?>" required maxlength="255"></div><div class="inline-fields"><div class="field"><label>URL-slug</label><input name="slug" value="<?=e($p['slug'])?>"></div><div class="field"><label>Рубрика</label><select name="category_id"><option value="">Без рубрики</option><?php foreach($cats as $c):?><option value="<?=(int)$c['id']?>" <?=(string)$p['category_id']===(string)$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></div></div><div class="field"><label>Короткий анонс</label><textarea name="excerpt" style="min-height:100px"><?=e($p['excerpt'])?></textarea></div><div class="field"><label>URL изображения</label><input name="image_url" type="url" value="<?=e($p['image_url'])?>" placeholder="https://..."></div><div class="field"><label>Текст статьи (базовый HTML)</label><textarea name="content" required><?=e($p['content'])?></textarea></div><div class="inline-fields"><div class="field"><label>Статус</label><select name="status"><option value="draft" <?=$p['status']==='draft'?'selected':''?>>Черновик</option><option value="published" <?=$p['status']==='published'?'selected':''?>>Опубликовано</option></select></div><div class="field"><label>Дата публикации</label><input name="published_at" type="datetime-local" value="<?=e($p['published_at'])?>"></div></div><label><input type="checkbox" name="is_featured" value="1" <?=!empty($p['is_featured'])?'checked':''?>> Сделать главным материалом</label><div class="actions"><button class="btn">Сохранить</button><a class="btn btn-secondary" href="<?=e(url('admin/index.php'))?>">Отмена</a></div></form><?php require_once __DIR__.'/_footer.php';?>
